<?php

declare(strict_types=1);

namespace Ship\Docker;

/**
 * Renders the shell script for the prod stage's ENTRYPOINT. Generated by `ship build`/`ship
 * release` (see ProductionBuildRunner) rather than shipped as a stub, since its content depends on
 * which FrameworkAdapter matches.
 */
final class EntrypointScriptBuilder
{
    /**
     * @param list<string> $releaseCommands framework adapters'
     *        FrameworkAdapter::releaseCommands(), already flattened
     */
    public function build(array $releaseCommands): string
    {
        $lines = [
            '#!/bin/sh',
            '',
            '# Generated by `ship build`/`ship release` -- do not edit by hand, it will be',
            '# overwritten on the next one. Runs once per container',
            '# boot, before the real process starts, so real runtime secrets',
            '# (injected via compose environment:/env_file:, never baked into',
            '# the image) are present for anything here that needs them,',
            '# e.g. Laravel\'s artisan optimize or Symfony\'s cache:clear.',
            'set -e',
            '',
        ];

        foreach ($releaseCommands as $command) {
            $lines[] = $command;
        }

        $lines[] = '';
        // Release commands run as root, but php-fpm's workers run as www-data and need to write
        // here at request time. Limited to the directories a framework writes to: chowning
        // vendor/ too adds tens of seconds to every boot. "database" covers Laravel's default
        // SQLite file, whose directory must be writable for journal files.
        $lines[] = 'for dir in storage bootstrap/cache database var; do';
        $lines[] = '    [ -d "$dir" ] && chown -R www-data:www-data "$dir"';
        $lines[] = 'done';
        $lines[] = '';
        // Decided per container at runtime, since one image backs containers with opposite
        // needs: php-fpm's master must start as root, while an Octane server, Horizon or the
        // scheduler should not run as root at all. The compose file sets SHIP_RUN_AS on those.
        // su-exec on the Alpine image, setpriv on FrankenPHP's Debian one.
        $lines[] = 'if [ -n "$SHIP_RUN_AS" ]; then';
        $lines[] = '    if command -v su-exec >/dev/null 2>&1; then';
        $lines[] = '        exec su-exec "$SHIP_RUN_AS" "$@"';
        $lines[] = '    elif command -v setpriv >/dev/null 2>&1; then';
        $lines[] = '        exec setpriv --reuid="$SHIP_RUN_AS" --regid="$SHIP_RUN_AS" --clear-groups --no-new-privs "$@"';
        $lines[] = '    fi';
        $lines[] = 'fi';
        // exec makes the real server PID 1, so `docker stop`'s SIGTERM reaches it. su-exec and
        // setpriv exec their target directly too.
        $lines[] = 'exec "$@"';
        $lines[] = '';

        return implode("\n", $lines);
    }
}
